import React, { useState } from 'react';
import Blobs    from '../components/Blobs';
import Orb3D    from '../components/Orb3D';
import { analyzeThought } from '../hooks/useGroq';
import { useThoughts }    from '../hooks/useStorage';

export default function Home({ setPage, streak }) {
  const [text,    setText]    = useState('');
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState('');
  const [result,  setResult]  = useState(null);
  const { addThought } = useThoughts();

  const handleSubmit = async () => {
    if (!text.trim() || loading) return;
    setLoading(true); setError('');
    try {
      const ai = await analyzeThought(text);
      const entry = { id:Date.now(), user_text:text, ...ai, date:new Date().toISOString() };
      addThought(entry);
      setResult(entry);
    } catch { setError('Kunde inte analysera just nu. Försök igen.'); }
    setLoading(false);
  };

  if (result) return <Analysis result={result} text={text} onBack={() => { setResult(null); setText(''); }} setPage={setPage} />;

  return (
    <div style={{ minHeight:'100vh', position:'relative' }}>
      <Blobs variant="default" />
      <div style={{ position:'relative', zIndex:1, display:'flex', flexDirection:'column', alignItems:'center', padding:'80px 24px 60px', maxWidth:600, margin:'0 auto' }}>

        {/* 3D Orb — the visual hero */}
        <div style={{ marginBottom:48, position:'relative', animation:'fadeIn .8s ease both' }}>
          <Orb3D size={220} colors={['#7050d0','#2a1870','#a080f0']} />
          {/* Label floating over orb */}
          <div style={{ position:'absolute', bottom:16, left:'50%', transform:'translateX(-50%)', background:'rgba(10,10,15,0.7)', backdropFilter:'blur(12px)', border:'1px solid rgba(255,255,255,0.1)', borderRadius:100, padding:'5px 14px', whiteSpace:'nowrap' }}>
            <span style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.14em', color:'rgba(255,255,255,0.6)' }}>MENTAL HEALTH · KBT</span>
          </div>
        </div>

        {/* Large editorial heading */}
        <div style={{ width:'100%', marginBottom:40, animation:'fadeUp .8s .1s cubic-bezier(0.16,1,0.3,1) both' }}>
          <h1 style={{ fontSize:'clamp(44px,10vw,72px)', fontWeight:700, letterSpacing:'-0.05em', lineHeight:0.88, color:'#fff', marginBottom:16 }}>
            BRYT<br/><span style={{ color:'rgba(255,255,255,0.2)' }}>TANKE-<br/>SPIRALEN</span>
          </h1>
          <p style={{ fontSize:15, color:'rgba(255,255,255,0.45)', lineHeight:1.8, fontWeight:300, maxWidth:380 }}>
            Skriv ner vad du tänker. AI:n identifierar tankefällan och ger dig en objektiv omramning.
          </p>
        </div>

        {streak > 0 && (
          <div style={{ alignSelf:'flex-start', display:'inline-flex', alignItems:'center', gap:8, padding:'6px 14px', borderRadius:100, background:'rgba(255,255,255,0.06)', border:'1px solid rgba(255,255,255,0.08)', marginBottom:24, fontSize:12, color:'rgba(255,255,255,0.55)', animation:'fadeUp .8s .2s both' }}>
            🔥 {streak} dag{streak>1?'ar':''} i rad
          </div>
        )}

        {/* Glass input card */}
        <div className="glass" style={{ width:'100%', borderRadius:24, padding:24, marginBottom:12, animation:'fadeUp .8s .2s cubic-bezier(0.16,1,0.3,1) both' }}>
          <div style={{ display:'flex', alignItems:'center', gap:8, marginBottom:14 }}>
            <div style={{ width:6, height:6, borderRadius:'50%', background:'rgba(140,100,255,0.8)', animation:'pulse 2s infinite' }} />
            <span style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.16em', textTransform:'uppercase', color:'rgba(255,255,255,0.3)' }}>Vad snurrar i huvudet?</span>
          </div>
          <textarea value={text} onChange={e=>setText(e.target.value)} maxLength={1000}
            placeholder="Skriv fritt..."
            style={{ width:'100%', minHeight:120, background:'transparent', border:'none', color:'#fff', fontSize:15, fontWeight:300, lineHeight:1.75, resize:'none', outline:'none' }}
          />
          <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginTop:12, paddingTop:14, borderTop:'1px solid rgba(255,255,255,0.06)' }}>
            <span style={{ fontFamily:'DM Mono,monospace', fontSize:10, color:'rgba(255,255,255,0.18)' }}>{text.length}/1000</span>
            <button onClick={handleSubmit} disabled={!text.trim()||loading}
              style={{ padding:'10px 22px', borderRadius:100, fontSize:13, fontWeight:600, transition:'all .25s', background: text.trim()&&!loading ? 'rgba(255,255,255,0.95)' : 'rgba(255,255,255,0.08)', color: text.trim()&&!loading ? '#0a0a0f' : 'rgba(255,255,255,0.25)', border:'none' }}>
              {loading
                ? <span style={{ display:'flex',alignItems:'center',gap:8 }}><span style={{ width:11,height:11,border:'2px solid rgba(0,0,0,0.25)',borderTopColor:'#000',borderRadius:'50%',display:'inline-block',animation:'spin .7s linear infinite' }}/>Analyserar...</span>
                : 'Analysera →'}
            </button>
          </div>
          {error && <p style={{ color:'rgba(255,120,120,0.8)', fontSize:12, marginTop:10 }}>{error}</p>}
        </div>

        {/* Breathing shortcut */}
        <button onClick={()=>setPage('breathing')} className="glass"
          style={{ width:'100%', padding:'16px 20px', borderRadius:16, display:'flex', alignItems:'center', justifyContent:'space-between', color:'rgba(255,255,255,0.45)', fontSize:13, transition:'all .25s', animation:'fadeUp .8s .3s both' }}
          onMouseEnter={e=>{e.currentTarget.style.color='#fff';e.currentTarget.style.background='rgba(255,255,255,0.08)'}}
          onMouseLeave={e=>{e.currentTarget.style.color='rgba(255,255,255,0.45)';e.currentTarget.style.background='rgba(255,255,255,0.05)'}}>
          <span style={{ display:'flex', alignItems:'center', gap:10 }}>
            <span style={{ fontSize:18 }}>🫁</span>
            <span>4-7-8 Andningsövning</span>
          </span>
          <span style={{ fontFamily:'DM Mono,monospace', fontSize:10 }}>→</span>
        </button>
      </div>
    </div>
  );
}

function Analysis({ result, text, onBack, setPage }) {
  return (
    <div style={{ minHeight:'100vh', position:'relative' }}>
      <Blobs variant="warm" />
      <div style={{ position:'relative', zIndex:1, padding:'80px 24px 60px', maxWidth:560, margin:'0 auto', animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>

        {/* Orb — different colours for analysis */}
        <div style={{ display:'flex', justifyContent:'center', marginBottom:40 }}>
          <div style={{ position:'relative' }}>
            <Orb3D size={160} colors={['#a04080','#601030','#d060a0']} speed={0.3} />
            <div style={{ position:'absolute', inset:0, display:'flex', alignItems:'center', justifyContent:'center' }}>
              <span style={{ fontSize:28 }}>{result.trap_icon}</span>
            </div>
          </div>
        </div>

        {/* Big trap label */}
        <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(255,255,255,0.25)', marginBottom:10 }}>Tankefälla identifierad</p>
        <h2 style={{ fontSize:'clamp(32px,7vw,52px)', fontWeight:700, letterSpacing:'-0.04em', lineHeight:0.92, color:'#fff', marginBottom:32 }}>{result.trap_label}</h2>

        {/* What you wrote */}
        <div style={{ borderLeft:'2px solid rgba(255,255,255,0.1)', paddingLeft:16, marginBottom:32, fontSize:14, color:'rgba(255,255,255,0.35)', fontStyle:'italic', lineHeight:1.7 }}>"{text}"</div>

        {/* Glass info cards */}
        {[
          { label:'Vad händer i dina tankar', content:result.description },
          { label:'Objektiv omramning',        content:result.reframe },
          { label:'💡 Prova den här övningen', content:result.exercise_text },
        ].map(({ label, content }) => (
          <div key={label} className="glass" style={{ borderRadius:20, padding:'22px', marginBottom:12 }}>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(255,255,255,0.28)', marginBottom:10 }}>{label}</p>
            <p style={{ fontSize:14, color:'rgba(255,255,255,0.75)', lineHeight:1.85, fontWeight:300 }}>{content}</p>
          </div>
        ))}

        {result.second_trap && result.second_trap !== 'null' && (
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:10, color:'rgba(255,255,255,0.25)', marginBottom:20 }}>Möjlig sekundär: {result.second_trap}</p>
        )}

        <div style={{ display:'flex', gap:12, flexWrap:'wrap', marginTop:8 }}>
          <button onClick={()=>setPage('breathing')} className="glass"
            style={{ flex:1, padding:'14px', borderRadius:14, color:'rgba(255,255,255,0.65)', fontSize:13, transition:'all .2s', minWidth:140 }}
            onMouseEnter={e=>{e.currentTarget.style.color='#fff';e.currentTarget.style.background='rgba(255,255,255,0.09)'}}
            onMouseLeave={e=>{e.currentTarget.style.color='rgba(255,255,255,0.65)';e.currentTarget.style.background='rgba(255,255,255,0.05)'}}>
            🫁 Andningsövning
          </button>
          <button onClick={onBack} style={{ padding:'14px 24px', borderRadius:14, color:'rgba(255,255,255,0.3)', fontSize:13 }}>← Tillbaka</button>
        </div>
      </div>
    </div>
  );
}
